```javascript
import { useSelector, shallowEqual } from 'react-redux';
import { useTransition } from 'react';

function MetricsContainer() {
  const [isPending, startTransition] = useTransition();
  const buckets = useSelector(state => state.metrics.buckets, shallowEqual);

  // Defer heavy UI work during bursts
  startTransition(() => {
    // update chart data, etc.
  });

  return <MetricsPanel data={buckets} />;
}
